import starlight from "@astrojs/starlight";
import svelte from "@astrojs/svelte";
import { defineConfig } from "astro/config";
import starlightTypeDoc, { typeDocSidebarGroup } from "starlight-typedoc";

/**
 * Contributor reference for `@fndvit/gen-tilesets` and the editor.
 *
 * Every page is written from source (`.ts`, `.svelte`, `*.test.ts`) only, never
 * from the repository's Markdown. The API section is generated by TypeDoc from
 * the two public entry points at build time and is not committed, so it cannot
 * drift from the exports.
 */
export default defineConfig({
  // The demo holds 5173 and the editor 5174.
  server: { port: 5175 },
  integrations: [
    svelte(),
    starlight({
      title: "gen-tilesets internals",
      plugins: [
        starlightTypeDoc({
          entryPoints: [
            "../../packages/tileset/src/index.ts",
            "../../packages/tileset/src/render/index.ts",
          ],
          tsconfig: "../../packages/tileset/tsconfig.json",
          output: "api",
          sidebar: { label: "API reference", collapsed: true },
          typeDoc: { excludeInternal: false, readme: "none" },
        }),
      ],
      sidebar: [
        { label: "Start here", link: "/" },
        { label: "Concepts", items: [{ autogenerate: { directory: "concepts" } }] },
        { label: "Engine", items: [{ autogenerate: { directory: "engine" } }] },
        { label: "Renderer", items: [{ autogenerate: { directory: "renderer" } }] },
        { label: "Editor", items: [{ autogenerate: { directory: "editor" } }] },
        typeDocSidebarGroup,
        { label: "Review findings", link: "/review-findings/" },
      ],
    }),
  ],
});
